    """Raise ValueError for empty or ragged input, TypeError for bad elements."""
    if not m or not all(m):
        raise ValueError("matrix must be a non-empty list of non-empty rows")
    width = len(m[0])
    if any(len(row) != width for row in m):
        raise ValueError("matrix rows must all have the same length")
    for row in m:
        for x in row:
            if not isinstance(x, (int, float, Fraction)):
                raise TypeError(f"unsupported matrix element: {x!r}")


def _check_square(m: Matrix) -> None:
    _check_matrix(m)
    if len(m) != len(m[0]):
        raise ValueError("determinant requires a square matrix")


def transpose(m: Matrix) -> Matrix:
    _check_matrix(m)
    return [list(col) for col in zip(*m)]


def matmul(a: Matrix, b: Matrix) -> Matrix:
    _check_matrix(a)
